CREATE TABLE IF NOT EXISTS societies (id text PRIMARY KEY, name text NOT NULL, address text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','pending','suspended')), plan text NOT NULL DEFAULT 'starter', created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS users (id text PRIMARY KEY, name text NOT NULL, email text UNIQUE NOT NULL, password_hash text, platform_role text NOT NULL DEFAULT 'user', created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS sessions (token_hash text PRIMARY KEY,user_id text REFERENCES users(id) ON DELETE CASCADE,expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS profiles (id text PRIMARY KEY REFERENCES users(id), phone text DEFAULT '', preferences jsonb NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS society_memberships(id text PRIMARY KEY,society_id text REFERENCES societies(id),user_id text REFERENCES users(id),role text NOT NULL CHECK(role IN ('admin','resident','guard','maintenance')),created_at timestamptz DEFAULT now(), UNIQUE(society_id,user_id));
CREATE TABLE IF NOT EXISTS buildings (id text PRIMARY KEY,society_id text NOT NULL REFERENCES societies(id),name text NOT NULL, kind text NOT NULL DEFAULT 'Apartment',created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(society_id,id));
CREATE INDEX IF NOT EXISTS buildings_tenant ON buildings(society_id,created_at);
CREATE TABLE IF NOT EXISTS floors (id text PRIMARY KEY,society_id text NOT NULL REFERENCES societies(id),building_id text NOT NULL, name text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(society_id,id));
CREATE INDEX IF NOT EXISTS floors_tenant ON floors(society_id,created_at);
CREATE TABLE IF NOT EXISTS units (id text PRIMARY KEY,society_id text NOT NULL REFERENCES societies(id),building_id text NOT NULL, floor_id text, name text NOT NULL, status text NOT NULL DEFAULT 'vacant',created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(society_id,id));
CREATE INDEX IF NOT EXISTS units_tenant ON units(society_id,created_at);
CREATE TABLE IF NOT EXISTS unit_occupancies (id text PRIMARY KEY,society_id text NOT NULL REFERENCES societies(id),unit_id text NOT NULL, user_id text REFERENCES users(id), kind text NOT NULL DEFAULT 'tenant',created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(society_id,id));
CREATE INDEX IF NOT EXISTS unit_occupancies_tenant ON unit_occupancies(society_id,created_at);
CREATE TABLE IF NOT EXISTS invitations (id text PRIMARY KEY,society_id text NOT NULL REFERENCES societies(id),email text NOT NULL, role text NOT NULL, token_hash text UNIQUE NOT NULL, expires_at timestamptz NOT NULL, status text NOT NULL DEFAULT 'pending',created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(society_id,id));
CREATE INDEX IF NOT EXISTS invitations_tenant ON invitations(society_id,created_at);
CREATE TABLE IF NOT EXISTS visitor_passes (id text PRIMARY KEY,society_id text NOT NULL REFERENCES societies(id),user_id text REFERENCES users(id), unit_id text, name text NOT NULL, purpose text NOT NULL, vehicle text DEFAULT '', starts_at timestamptz NOT NULL, ends_at timestamptz NOT NULL, allowed_entries int NOT NULL DEFAULT 1 CHECK(allowed_entries BETWEEN 1 AND 20), used_entries int NOT NULL DEFAULT 0, token_hash text UNIQUE NOT NULL, status text NOT NULL DEFAULT 'active', CHECK(ends_at>starts_at),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(society_id,id));
CREATE INDEX IF NOT EXISTS visitor_passes_tenant ON visitor_passes(society_id,created_at);
CREATE TABLE IF NOT EXISTS visitor_entries (id text PRIMARY KEY,society_id text NOT NULL REFERENCES societies(id),pass_id text NOT NULL, guard_id text REFERENCES users(id), checked_in timestamptz NOT NULL DEFAULT now(), checked_out timestamptz,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(society_id,id));
CREATE INDEX IF NOT EXISTS visitor_entries_tenant ON visitor_entries(society_id,created_at);
CREATE TABLE IF NOT EXISTS complaints (id text PRIMARY KEY,society_id text NOT NULL REFERENCES societies(id),user_id text REFERENCES users(id), unit_id text NOT NULL, title text NOT NULL, description text NOT NULL, category text NOT NULL, priority text NOT NULL DEFAULT 'normal', status text NOT NULL DEFAULT 'open', assigned_to text REFERENCES users(id), due_at timestamptz NOT NULL DEFAULT now()+interval '3 days',created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(society_id,id));
CREATE INDEX IF NOT EXISTS complaints_tenant ON complaints(society_id,created_at);
CREATE TABLE IF NOT EXISTS complaint_comments (id text PRIMARY KEY,society_id text NOT NULL REFERENCES societies(id),complaint_id text NOT NULL, user_id text REFERENCES users(id), body text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(society_id,id));
CREATE INDEX IF NOT EXISTS complaint_comments_tenant ON complaint_comments(society_id,created_at);
CREATE TABLE IF NOT EXISTS maintenance_assignments (id text PRIMARY KEY,society_id text NOT NULL REFERENCES societies(id),complaint_id text NOT NULL, user_id text REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(society_id,id));
CREATE INDEX IF NOT EXISTS maintenance_assignments_tenant ON maintenance_assignments(society_id,created_at);
CREATE TABLE IF NOT EXISTS maintenance_updates (id text PRIMARY KEY,society_id text NOT NULL REFERENCES societies(id),complaint_id text NOT NULL, user_id text REFERENCES users(id), body text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(society_id,id));
CREATE INDEX IF NOT EXISTS maintenance_updates_tenant ON maintenance_updates(society_id,created_at);
CREATE TABLE IF NOT EXISTS invoices (id text PRIMARY KEY,society_id text NOT NULL REFERENCES societies(id),unit_id text NOT NULL, title text NOT NULL, amount_cents int NOT NULL CHECK(amount_cents>0), paid_cents int NOT NULL DEFAULT 0 CHECK(paid_cents>=0), due_at timestamptz NOT NULL, status text NOT NULL DEFAULT 'unpaid', CHECK(paid_cents<=amount_cents),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(society_id,id));
CREATE INDEX IF NOT EXISTS invoices_tenant ON invoices(society_id,created_at);
CREATE TABLE IF NOT EXISTS invoice_items (id text PRIMARY KEY,society_id text NOT NULL REFERENCES societies(id),invoice_id text NOT NULL, title text NOT NULL, amount_cents int NOT NULL CHECK(amount_cents>0),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(society_id,id));
CREATE INDEX IF NOT EXISTS invoice_items_tenant ON invoice_items(society_id,created_at);
CREATE TABLE IF NOT EXISTS payments (id text PRIMARY KEY,society_id text NOT NULL REFERENCES societies(id),invoice_id text NOT NULL, user_id text REFERENCES users(id), amount_cents int NOT NULL CHECK(amount_cents>0), reference text NOT NULL, status text NOT NULL DEFAULT 'pending',created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(society_id,id));
CREATE INDEX IF NOT EXISTS payments_tenant ON payments(society_id,created_at);
CREATE TABLE IF NOT EXISTS facilities (id text PRIMARY KEY,society_id text NOT NULL REFERENCES societies(id),name text NOT NULL, description text NOT NULL, capacity int NOT NULL CHECK(capacity>0), fee_cents int NOT NULL DEFAULT 0 CHECK(fee_cents>=0),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(society_id,id));
CREATE INDEX IF NOT EXISTS facilities_tenant ON facilities(society_id,created_at);
CREATE TABLE IF NOT EXISTS facility_bookings (id text PRIMARY KEY,society_id text NOT NULL REFERENCES societies(id),facility_id text NOT NULL, user_id text REFERENCES users(id), title text NOT NULL, starts_at timestamptz NOT NULL, ends_at timestamptz NOT NULL, status text NOT NULL DEFAULT 'pending', CHECK(ends_at>starts_at),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(society_id,id));
CREATE INDEX IF NOT EXISTS facility_bookings_tenant ON facility_bookings(society_id,created_at);
CREATE TABLE IF NOT EXISTS announcements (id text PRIMARY KEY,society_id text NOT NULL REFERENCES societies(id),user_id text REFERENCES users(id), title text NOT NULL, body text NOT NULL, priority text NOT NULL DEFAULT 'normal',created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(society_id,id));
CREATE INDEX IF NOT EXISTS announcements_tenant ON announcements(society_id,created_at);
CREATE TABLE IF NOT EXISTS announcement_reads (id text PRIMARY KEY,society_id text NOT NULL REFERENCES societies(id),announcement_id text NOT NULL, user_id text REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(society_id,id));
CREATE INDEX IF NOT EXISTS announcement_reads_tenant ON announcement_reads(society_id,created_at);
CREATE TABLE IF NOT EXISTS notifications (id text PRIMARY KEY,society_id text NOT NULL REFERENCES societies(id),user_id text REFERENCES users(id), title text NOT NULL, body text NOT NULL, read_at timestamptz, dedupe_key text UNIQUE,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(society_id,id));
CREATE INDEX IF NOT EXISTS notifications_tenant ON notifications(society_id,created_at);
CREATE TABLE IF NOT EXISTS documents (id text PRIMARY KEY,society_id text NOT NULL REFERENCES societies(id),user_id text REFERENCES users(id), title text NOT NULL, storage_key text NOT NULL, mime text NOT NULL, bytes int NOT NULL, entity_type text NOT NULL DEFAULT 'community', entity_id text,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(society_id,id));
CREATE INDEX IF NOT EXISTS documents_tenant ON documents(society_id,created_at);
CREATE TABLE IF NOT EXISTS polls (id text PRIMARY KEY,society_id text NOT NULL REFERENCES societies(id),title text NOT NULL, ends_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(society_id,id));
CREATE INDEX IF NOT EXISTS polls_tenant ON polls(society_id,created_at);
CREATE TABLE IF NOT EXISTS poll_options (id text PRIMARY KEY,society_id text NOT NULL REFERENCES societies(id),poll_id text NOT NULL, title text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(society_id,id));
CREATE INDEX IF NOT EXISTS poll_options_tenant ON poll_options(society_id,created_at);
CREATE TABLE IF NOT EXISTS poll_votes (id text PRIMARY KEY,society_id text NOT NULL REFERENCES societies(id),poll_id text NOT NULL, option_id text NOT NULL, user_id text REFERENCES users(id), UNIQUE(poll_id,user_id),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(society_id,id));
CREATE INDEX IF NOT EXISTS poll_votes_tenant ON poll_votes(society_id,created_at);
CREATE TABLE IF NOT EXISTS audit_logs (id text PRIMARY KEY,society_id text NOT NULL REFERENCES societies(id),user_id text REFERENCES users(id), action text NOT NULL, entity_id text, details jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(society_id,id));
CREATE INDEX IF NOT EXISTS audit_logs_tenant ON audit_logs(society_id,created_at);
CREATE TABLE IF NOT EXISTS automation_jobs (id text PRIMARY KEY,society_id text NOT NULL REFERENCES societies(id),name text NOT NULL, last_run timestamptz, status text DEFAULT 'ready',created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(society_id,id));
CREATE INDEX IF NOT EXISTS automation_jobs_tenant ON automation_jobs(society_id,created_at);
CREATE TABLE IF NOT EXISTS security_incidents (id text PRIMARY KEY,society_id text NOT NULL REFERENCES societies(id),user_id text REFERENCES users(id), title text NOT NULL, description text NOT NULL, priority text NOT NULL DEFAULT 'normal', status text NOT NULL DEFAULT 'open',created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(society_id,id));
CREATE INDEX IF NOT EXISTS security_incidents_tenant ON security_incidents(society_id,created_at);
CREATE TABLE IF NOT EXISTS community_events (id text PRIMARY KEY,society_id text NOT NULL REFERENCES societies(id),title text NOT NULL, description text NOT NULL, starts_at timestamptz NOT NULL, location text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(society_id,id));
CREATE INDEX IF NOT EXISTS community_events_tenant ON community_events(society_id,created_at);
CREATE TABLE IF NOT EXISTS feedback (id text PRIMARY KEY,society_id text NOT NULL REFERENCES societies(id),user_id text REFERENCES users(id), title text NOT NULL, body text NOT NULL, status text NOT NULL DEFAULT 'open',created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(society_id,id));
CREATE INDEX IF NOT EXISTS feedback_tenant ON feedback(society_id,created_at);
CREATE TABLE IF NOT EXISTS lost_found_reports (id text PRIMARY KEY,society_id text NOT NULL REFERENCES societies(id),user_id text REFERENCES users(id), title text NOT NULL, description text NOT NULL, kind text NOT NULL, status text NOT NULL DEFAULT 'open',created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(society_id,id));
CREATE INDEX IF NOT EXISTS lost_found_reports_tenant ON lost_found_reports(society_id,created_at);
CREATE TABLE IF NOT EXISTS support_requests (id text PRIMARY KEY,society_id text NOT NULL REFERENCES societies(id),user_id text REFERENCES users(id), title text NOT NULL, body text NOT NULL, status text NOT NULL DEFAULT 'open',created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(society_id,id));
CREATE INDEX IF NOT EXISTS support_requests_tenant ON support_requests(society_id,created_at);
CREATE TABLE IF NOT EXISTS society_subscriptions (id text PRIMARY KEY,society_id text NOT NULL REFERENCES societies(id),plan text NOT NULL, status text NOT NULL DEFAULT 'active',created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(society_id,id));
CREATE INDEX IF NOT EXISTS society_subscriptions_tenant ON society_subscriptions(society_id,created_at);
