CREATE TABLE emergency_contacts (id text PRIMARY KEY,society_id text NOT NULL REFERENCES societies(id),name text NOT NULL,phone text NOT NULL,description text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE shifts (id text PRIMARY KEY,society_id text NOT NULL REFERENCES societies(id),user_id text NOT NULL REFERENCES users(id),title text NOT NULL,starts_at timestamptz NOT NULL,ends_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),CHECK(ends_at>starts_at));
CREATE OR REPLACE FUNCTION prevent_booking_overlap() RETURNS trigger AS $$
BEGIN
 PERFORM id FROM facilities WHERE id=NEW.facility_id FOR UPDATE;
 IF NEW.status IN ('pending','approved') AND EXISTS(SELECT 1 FROM facility_bookings b WHERE b.facility_id=NEW.facility_id AND b.id<>NEW.id AND b.status IN ('pending','approved') AND b.starts_at<NEW.ends_at AND b.ends_at>NEW.starts_at) THEN
 RAISE EXCEPTION 'Booking overlaps an existing reservation' USING ERRCODE='23505';
 END IF;
 RETURN NEW;
END; $$ LANGUAGE plpgsql;
CREATE TRIGGER booking_overlap BEFORE INSERT OR UPDATE ON facility_bookings FOR EACH ROW EXECUTE FUNCTION prevent_booking_overlap();
